insert into public.blocks (page_id, type, label, sort, data)
select p.id, b->>'type', b->>'label', (t.i - 1)::int, b->'data'
from public.pages p,
     jsonb_array_elements($concept$[{"type":"gidsKop","label":"Kop","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Gids · Wet verbetering poortwachter","kruimel":"Wet verbetering poortwachter","heading":"Wat zijn de stappen van de Wet verbetering poortwachter?","antwoord":"De Wet verbetering poortwachter schrijft voor wat werkgever en werknemer in de eerste twee ziektejaren doen om terugkeer naar werk mogelijk te maken: ziekmelding in week 1, probleemanalyse in week 6, plan van aanpak in week 8, melding bij UWV in week 42, eerstejaarsevaluatie in week 52 en de WIA-aanvraag rond week 91. Doe je te weinig of te laat, dan kan UWV je tot een jaar langer loon laten doorbetalen.","text":"Deze gids zet alle stappen en termijnen op een rij, legt uit wat jij doet en wat de bedrijfsarts en UWV doen, en laat zien waar het meestal misgaat.","auteur":{"naam":"Naam collega (invullen)","functie":"Functie (invullen)"},"gepubliceerd":"2026-10-22","bijgewerkt":"2026-11-23"}},{"type":"gidsTekst","label":"Wat is de wet","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Wat is de Wet verbetering poortwachter?","tekst":"De Wet verbetering poortwachter bestaat sinds 2002 en geldt voor elke werkgever in Nederland, ook als je één medewerker in dienst hebt. De wet verplicht werkgever en werknemer om samen actief te werken aan herstel en terugkeer naar werk. Het woord poortwachter slaat op UWV: die bewaakt de poort naar de WIA en kijkt na twee jaar of jullie genoeg hebben gedaan.\n\nAls werkgever betaal je bij ziekte maximaal twee jaar, 104 weken, loon door. De wet schrijft minimaal 70 procent voor; in het eerste jaar nooit minder dan het minimumloon, en veel cao’s zitten daarboven. In die twee jaar laat je aantoonbaar zien dat je er alles aan hebt gedaan om je medewerker weer aan het werk te helpen, in het eigen werk of in ander werk.\n\nAan het eind van het traject beoordeelt UWV de WIA-aanvraag én de re-integratie-inspanningen. Zijn de stappen op tijd gezet en goed vastgelegd, dan stopt je loondoorbetaling na 104 weken. Ontbreekt er iets, dan kan een loonsanctie volgen: maximaal 52 weken extra loon doorbetalen.\n\nHet gaat in de kern niet om formulieren afvinken. Het doel is dat mensen duurzaam terugkeren naar werk; de stappen zijn het houvast om daar samen naartoe te werken. Daarom begint elke stap met een gesprek, en pas daarna met een document.","kader":{"eyebrow":"Goed om te weten","titel":"Drie partijen, één dossier","tekst":"**Jij** bent eindverantwoordelijk voor de re-integratie en voor het dossier. **De bedrijfsarts** beoordeelt wat je medewerker medisch gezien kan. **UWV** toetst na twee jaar of jullie genoeg hebben gedaan. Een arbodienst neemt de uitvoering en de termijnbewaking van je over, maar niet de verantwoordelijkheid.","href":"/bedrijfsarts","label":"Lees de gids over de bedrijfsarts"}}},{"type":"gidsTijdlijn","label":"Tijdlijn","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Van week 1 tot week 104","heading":"Alle stappen van de Wet verbetering poortwachter","text":"De weken tellen vanaf de eerste ziektedag. Per stap staat wie aan zet is: jij, je medewerker, de bedrijfsarts of UWV.","items":[{"wanneer":"Week 1","titel":"Ziekmelding bij de arbodienst","wie":"Werkgever","tekst":"Meldt een medewerker zich ziek, dan geef je dat uiterlijk binnen een week door aan je arbodienst. Hoe eerder, hoe beter: bij React2u meld je op de eerste dag, en belt je casemanager binnen één werkdag met jou en je medewerker."},{"wanneer":"Week 6","titel":"Probleemanalyse","wie":"Bedrijfsarts","tekst":"De bedrijfsarts legt vast wat je medewerker nog kan, wat de verwachting voor herstel is en welk advies geldt voor werkhervatting. Medische details blijven tussen de medewerker en de arts; jij krijgt wat je nodig hebt om de re-integratie te sturen."},{"wanneer":"Week 8","titel":"Plan van aanpak","wie":"Werkgever en werknemer","tekst":"Op basis van de probleemanalyse spreken jij en je medewerker af wat het doel is, welke stappen jullie zetten en wanneer. Je wijst een casemanager aan die het traject coördineert en de termijnen bewaakt. Beiden ondertekenen het plan."},{"wanneer":"Elke 6 weken","titel":"Evalueren en bijstellen","wie":"Werkgever en werknemer","tekst":"Bespreek minimaal elke zes weken hoe het gaat en stel het plan bij als de situatie verandert. Leg ieder gesprek vast: dat is later het bewijs voor UWV."},{"wanneer":"Week 42","titel":"Ziekmelding bij UWV","wie":"Werkgever","tekst":"Is je medewerker nog ziek, dan meld je dat uiterlijk op de eerste werkdag na 42 weken bij UWV. Deze melding wordt geregeld vergeten; te laat melden kan een boete opleveren. Je casemanager herinnert je op tijd."},{"wanneer":"Week 52","titel":"Eerstejaarsevaluatie","wie":"Werkgever en werknemer","tekst":"Na een jaar sta je samen stil bij de vraag of terugkeer bij jou nog realistisch is: het opschudmoment. Is er geen concreet zicht op, dan start uiterlijk zes weken na deze evaluatie een tweedespoortraject bij een andere werkgever."},{"wanneer":"Rond week 88","titel":"WIA-aanvraag voorbereiden","wie":"UWV en werknemer","tekst":"Je medewerker krijgt van UWV een brief over het aanvragen van een WIA-uitkering. In deze weken stel je samen het re-integratieverslag samen: het complete verhaal van twee jaar, met alle documenten uit het dossier."},{"wanneer":"Week 91","titel":"Eindevaluatie en actueel oordeel","wie":"Werkgever, werknemer en bedrijfsarts","tekst":"Jij en je medewerker leggen in de eindevaluatie vast hoe het traject is verlopen. De bedrijfsarts voegt een actueel oordeel over de belastbaarheid toe."},{"wanneer":"Uiterlijk week 93","titel":"WIA-aanvraag","wie":"Werknemer","tekst":"Je medewerker vraagt de WIA aan, met het re-integratieverslag erbij. UWV beoordeelt eerst de re-integratie-inspanningen en pas daarna de arbeidsongeschiktheid."},{"wanneer":"Week 104","titel":"Einde loondoorbetaling","wie":"UWV","tekst":"Is UWV akkoord met de inspanningen, dan stopt je loondoorbetaling. Zo niet, dan volgt een loonsanctie: doorbetalen tot je het hersteld hebt, maximaal 52 weken."}],"noot":"Wordt je medewerker binnen vier weken na herstel opnieuw ziek, dan tellen de ziekteperiodes bij elkaar op en loopt de telling gewoon door."}},{"type":"gidsTekst","label":"Eerste en tweede spoor","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Eerste spoor en tweede spoor","tekst":"In de wet zie je twee sporen. Het **eerste spoor** is terugkeer bij jou als werkgever: in de eigen functie, in de eigen functie met aanpassingen, of in een andere functie binnen je organisatie. Het **tweede spoor** is re-integratie bij een andere werkgever, als terugkeer in je eigen bedrijf niet meer haalbaar is.\n\nHet tweede spoor start je zodra duidelijk is dat terugkeer bij jou niet lukt, en uiterlijk zes weken na de eerstejaarsevaluatie. Wie wacht, loopt risico op een loonsanctie. Een arbeidsdeskundig onderzoek, meestal rond week 42 tot 52, geeft het onderbouwde antwoord op de vraag welk spoor passend is.\n\nTwee sporen kunnen ook naast elkaar lopen. Als het eerste spoor onzeker is, start je het tweede spoor alvast. Wordt je medewerker daarna toch beter, dan stop je het tweede spoor gewoon weer. Dat is geen verspilde moeite: het laat UWV zien dat je op tijd hebt gehandeld.\n\nMeer over de sporen, de rol van de arbeidsdeskundige en wat je medewerker zelf moet doen lees je in de [gids over re-integratie](/re-integratie) en de [gids over het arbeidsdeskundig onderzoek](/arbeidsdeskundig-onderzoek)."}},{"type":"gidsTabel","label":"Termijnen","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Op een rij","heading":"Termijnen en documenten van de Wet verbetering poortwachter","text":"Elke stap hoort bij een document in het dossier. Samen vormen ze het re-integratieverslag dat UWV bij de WIA-aanvraag beoordeelt.","kolommen":["Moment","Stap","Wie","Document in het dossier"],"rijen":[["Dag 1","Ziekmelding bij de werkgever","Werknemer","Ziekmelding met datum"],["Week 1","Ziekmelding bij de arbodienst","Werkgever","Bevestiging van de arbodienst"],["Week 6","Probleemanalyse","Bedrijfsarts","Probleemanalyse met advies"],["Week 8","Plan van aanpak","Werkgever en werknemer","Plan van aanpak, ondertekend"],["Elke 6 weken","Voortgangsgesprek","Werkgever en werknemer","Bijstelling plan van aanpak"],["Week 42","Melding bij UWV","Werkgever","42e-weeksmelding"],["Week 52","Eerstejaarsevaluatie","Werkgever en werknemer","Eerstejaarsevaluatie, ondertekend"],["Week 88","Brief WIA-aanvraag","UWV","Brief van UWV"],["Week 91","Eindevaluatie en actueel oordeel","Werkgever, werknemer en bedrijfsarts","Eindevaluatie en actueel oordeel"],["Week 93","WIA-aanvraag","Werknemer","Re-integratieverslag compleet"],["Week 104","Einde loondoorbetaling","UWV","Beschikking van UWV"]],"noot":"Je medewerker krijgt van elk document een exemplaar en mag er zijn of haar eigen mening aan toevoegen. Bewaar het dossier minstens tot de beschikking van UWV, en langer als er bezwaar loopt."}},{"type":"gidsTekst","label":"Loonsanctie","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Wat als het misgaat: de loonsanctie","tekst":"Vindt UWV bij de WIA-aanvraag dat er te weinig is gedaan, dan legt het een loonsanctie op: je betaalt het loon maximaal 52 weken langer door en je medewerker krijgt in die tijd nog geen WIA-uitkering. UWV kijkt daarbij naar het resultaat én naar de inspanningen. Is je medewerker niet terug aan het werk, dan moet uit het dossier blijken dat jullie alles hebben geprobeerd wat redelijk was.\n\nVaak gaat het niet om onwil, maar om een vergeten melding, een ontbrekend verslag, een plan van aanpak dat nooit is bijgesteld of een tweede spoor dat te laat begon. Precies de dingen die een casemanager voor je bewaakt.\n\nHeb je een loonsanctie gekregen, dan kun je die laten bekorten: herstel wat ontbreekt, leg het vast en vraag UWV om een nieuwe beoordeling. Twijfel je onderweg of je op de goede weg zit? Vraag dan een **deskundigenoordeel** bij UWV: een onafhankelijk oordeel over bijvoorbeeld de re-integratie-inspanningen of de vraag of het aangeboden werk passend is. Het kost een werkgever 400 euro, een werknemer 100 euro.\n\n### Wat UWV precies beoordeelt\n\n- Is er op tijd een probleemanalyse en een plan van aanpak gemaakt?\n- Is het plan bijgesteld toen de situatie veranderde?\n- Is er genoeg gedaan om passend werk bij jou te vinden, bijvoorbeeld met een arbeidsdeskundig onderzoek?\n- Is het tweede spoor op tijd gestart, en was het een volwaardig traject?\n- Staan alle gesprekken, afspraken en documenten in het re-integratieverslag?"}},{"type":"gidsTekst","label":"Vijf fouten","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Vijf fouten die we het vaakst zien","tekst":"- **Te laat ziekmelden bij de arbodienst.** Een melding in week 3 betekent een probleemanalyse die al krap zit. Meld op dag één.\n- **Het plan van aanpak niet bijstellen.** Een plan uit week 8 dat in week 60 nog hetzelfde is, zegt UWV dat er niets is gebeurd. Elk voortgangsgesprek is een reden om iets te veranderen, of vast te leggen dat er niets verandert.\n- **De 42e-weeksmelding vergeten.** Een klein formulier met grote gevolgen: te laat melden kan een boete opleveren.\n- **Het tweede spoor uitstellen.** Hopen op herstel is menselijk, maar de wet vraagt om handelen. Twijfel je bij de eerstejaarsevaluatie, start dan en stop weer als het niet nodig blijkt.\n- **Afspraken niet vastleggen.** Een telefoontje dat niet in het dossier staat, heeft voor UWV niet plaatsgevonden.\n\nLees ook: [7 veelgemaakte fouten in het Poortwachter-traject](/blog/fouten-wet-verbetering-poortwachter) en [Wat is een loonsanctie en wanneer krijg je die?](/blog/loonsanctie-uwv)","kader":{"eyebrow":"Werkgevers","titel":"Wat jij doet en wat wij doen","tekst":"Op de werkgeverspagina staat per moment wat jouw verplichting is en wat React2u voor je regelt.","href":"/werkgevers#werkwijze","label":"Bekijk de werkwijze"}}},{"type":"gidsVragen","label":"Veelgestelde vragen","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Veelgestelde vragen","heading":"Vragen over de Wet verbetering poortwachter","text":"Staat je vraag er niet bij? Bel ons gerust, ook als je nog geen klant bent.","items":[{"question":"Geldt de Wet verbetering poortwachter ook voor kleine bedrijven?","answer":"Ja. Ook als je één medewerker in dienst hebt, gelden dezelfde stappen en termijnen. De wet maakt geen onderscheid naar grootte; de loonsanctie evenmin."},{"question":"Wie is verantwoordelijk voor de stappen?","answer":"Jij als werkgever bent eindverantwoordelijk voor de re-integratie en voor het dossier. De uitvoering en de termijnbewaking kun je uitbesteden aan een arbodienst, maar UWV spreekt jou aan als er iets ontbreekt."},{"question":"Moet mijn medewerker ook meewerken?","answer":"Ja. De wet geldt voor beide kanten. Je medewerker moet meewerken aan herstel en re-integratie, bijvoorbeeld door afspraken met de bedrijfsarts na te komen en passend werk te accepteren. Werkt hij of zij niet mee, dan mag je na een waarschuwing het loon opschorten of stopzetten."},{"question":"Wat gebeurt er als mijn medewerker tussendoor beter wordt?","answer":"Dan stopt het traject. Wordt je medewerker binnen vier weken opnieuw ziek, dan tellen de ziekteperiodes bij elkaar op en loopt de telling van de weken gewoon door. Na vier weken volledig werken begint een nieuwe telling."},{"question":"Hoe lang moet ik loon doorbetalen?","answer":"Maximaal 104 weken, minimaal 70 procent van het loon en in het eerste jaar nooit minder dan het minimumloon. Veel cao’s schrijven meer voor, vaak 100 procent in het eerste jaar. Krijg je een loonsanctie, dan komt daar maximaal 52 weken bij."},{"question":"Mag ik medische informatie vragen aan de bedrijfsarts?","answer":"Nee. De bedrijfsarts heeft een beroepsgeheim en deelt geen diagnose of behandeling. Je krijgt wel wat je nodig hebt: de beperkingen en mogelijkheden voor werk, de verwachte duur en het advies voor de re-integratie."},{"question":"Wat is een deskundigenoordeel en wanneer vraag ik dat aan?","answer":"Een onafhankelijk oordeel van UWV over een vraag in het traject: zijn de re-integratie-inspanningen voldoende, is het aangeboden werk passend, is de werknemer arbeidsongeschikt? Vraag het aan als jij en je medewerker het oneens zijn, of als je zeker wilt weten dat je op koers ligt. Het kost een werkgever 400 euro."}]}},{"type":"gidsHelpt","label":"Zo helpt React2u","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Zo helpt React2u","heading":"Al die termijnen bijhouden naast je bedrijf? Dat hoeft niet.","tekst":"Bij React2u krijg je een vaste casemanager die het hele traject bewaakt, van de eerste ziekmelding tot het re-integratieverslag. De bedrijfsarts maakt de probleemanalyse en blijft in contact met je medewerker. Wij houden het dossier op orde, zodat jij grip houdt zonder alle stappen zelf te hoeven onthouden.","punten":["Binnen één werkdag contact na een ziekmelding","Elke termijn bewaakt, elk document op tijd in het dossier","Eén vast aanspreekpunt voor jou en je medewerker","SBCA gecertificeerd en ISO 9001, 27001 en 27701"],"dienst":{"naam":"Recover","wat":"Verzuimbegeleiding voor werkgevers","tekst":"Casemanagement, bedrijfsarts, poortwachterdossier en UWV: alles onder één label.","href":"/recover","label":"Meer over React2u Recover"},"kennismaken":{"label":"Kennismaken","href":"/kennismaken"},"belTekst":"Of bel 085 620 58 00, ma t/m vr 9.00 tot 17.00 uur.","verwant":[{"label":"Gids: re-integratie","href":"/re-integratie"},{"label":"Gids: de bedrijfsarts","href":"/bedrijfsarts"},{"label":"Gids: arbeidsdeskundig onderzoek","href":"/arbeidsdeskundig-onderzoek"},{"label":"Loonsanctie voorkomen: checklist","href":"/blog/loonsanctie-voorkomen"}]}},{"type":"homeContact","label":"Contact","data":{"eyebrow":"Contact","heading":"Een vraag?\nBel gewoon even.","text":"Bel van maandag tot en met vrijdag tussen 9.00 en 17.00 uur, dan neemt een van ons op.","image":"/beeld/home/even-bellen.webp","alt":"Een vrouw belt ontspannen met React2u","focus":"52% 22%","routes":[{"icon":"phone","label":"Bellen · ma t/m vr 9.00 tot 17.00 uur","value":"085 620 58 00","href":"tel:+31856205800"},{"icon":"mail","label":"Mailen","value":"info@react2u.nl","href":"mailto:info@react2u.nl"},{"icon":"clock","label":"Liever teruggebeld?","value":"Plan een terugbelmoment","href":"/contact"}],"bg":"#ffffff"}}]$concept$::jsonb) with ordinality as t(b, i)
where p.slug = 'wet-verbetering-poortwachter';

update public.pages
set updated_at = now(),
    published = true
where slug = 'wet-verbetering-poortwachter';

-- /bedrijfsarts  (src/content/bedrijfsarts.json, 10 blokken)

-- Pagina aanmaken als hij nog niet bestaat; een bestaande pagina houdt zijn rij (en dus zijn id).
insert into public.pages (slug, title, published, sort, seo_title, seo_description)
values ('bedrijfsarts', 'Bedrijfsarts', true, 50, 'Bedrijfsarts: taken, spreekuur en basiscontract • React2u', 'Wat een bedrijfsarts doet bij verzuim en preventie, wat jij wel en niet te horen krijgt, wanneer je er een inschakelt en wat het basiscontract eist.')
on conflict (slug) do nothing;

-- De huidige blokken naar een verborgen reservepagina, met de oude titel en SEO — alleen als er blokken zijn.
insert into public.pages (slug, title, published, sort, seo_title, seo_description, og_image)
select 'bedrijfsarts-oud-20261123', p.title || ' (oud, 20261123)', false, 999, p.seo_title, p.seo_description, p.og_image
from public.pages p
where p.slug = 'bedrijfsarts'
  and exists (select 1 from public.blocks b where b.page_id = p.id);

update public.blocks
