insert into public.blocks (page_id, type, label, sort, data)
select p.id, b->>'type', b->>'label', (t.i - 1)::int, b->'data'
from public.pages p,
     jsonb_array_elements($concept$[{"type":"gidsKop","label":"Kop","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Gids · Bedrijfsarts","kruimel":"Bedrijfsarts","heading":"Wat doet een bedrijfsarts, en wanneer heb je er een nodig?","antwoord":"Een bedrijfsarts is een geregistreerd medisch specialist die beoordeelt wat een zieke werknemer nog kan, adviseert over herstel en werkhervatting en werkgevers helpt om uitval te voorkomen. Elke werkgever in Nederland moet toegang tot een bedrijfsarts geregeld hebben, in een basiscontract met een arbodienst of een zelfstandige bedrijfsarts.","text":"Deze gids legt uit wat de bedrijfsarts voor jou en je medewerkers doet, wat je wel en niet te horen krijgt, hoe de bedrijfsarts verschilt van een arboarts of huisarts, wat het basiscontract minimaal regelt en wat het kost.","auteur":{"naam":"Naam collega (invullen)","functie":"Functie (invullen)"},"gepubliceerd":"2026-11-23","bijgewerkt":"2026-11-23"}},{"type":"gidsTekst","label":"Wat doet de bedrijfsarts","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Wat een bedrijfsarts doet","tekst":"De bedrijfsarts is de medisch specialist voor arbeid en gezondheid. Na de opleiding tot basisarts volgt een specialisatie van vier jaar, en de titel is beschermd: alleen wie in het BIG-register staat als bedrijfsarts mag zich zo noemen. In een verzuimtraject is de bedrijfsarts de enige die een medisch oordeel mag geven over wat je medewerker kan en niet kan.\n\nDe taken van de bedrijfsarts vallen in drie groepen:\n\n### Bij verzuim\n\n- De **probleemanalyse** in week 6: beperkingen, mogelijkheden, verwachte duur en een advies voor de re-integratie.\n- **Spreekuren** gedurende het traject, om de belastbaarheid te volgen en het advies bij te stellen.\n- Een **belastbaarheidsprofiel** als basis voor het arbeidsdeskundig onderzoek, en het **actueel oordeel** in week 91 voor de WIA-aanvraag.\n- Advies over passend werk, opbouwschema’s en aanpassingen op de werkplek.\n\n### Bij preventie\n\n- Het **open spreekuur**: elke medewerker mag zonder ziekmelding, en zonder dat jij het weet, een afspraak maken bij vragen over gezondheid en werk.\n- Advies bij de **risico-inventarisatie en -evaluatie (RI&E)** en bij een preventief medisch onderzoek (PMO).\n- Een **werkplekbezoek** om de arbeidsomstandigheden met eigen ogen te zien.\n- Het signaleren en melden van **beroepsziekten**.\n\n### Bij keuringen\n\n- Aanstellingskeuringen waar de wet dat toestaat, rijbewijs- en Code 95-keuringen en periodieke keuringen voor functies met bijzondere eisen.\n\nIn de praktijk werkt de bedrijfsarts samen met een casemanager, die het traject coördineert, en vaak met een praktijkondersteuner of verzuimconsulent die onder taakdelegatie werkt: die voert spreekuren uit onder verantwoordelijkheid van de bedrijfsarts, met dezelfde geheimhouding. Zo is er vaker contact en blijft de bedrijfsarts beschikbaar voor de beoordeling.","kader":{"eyebrow":"Goed om te weten","titel":"Taakdelegatie","tekst":"De bedrijfsarts mag taken overdragen aan een gekwalificeerde ondersteuner, bijvoorbeeld het verzuimspreekuur. De bedrijfsarts blijft verantwoordelijk, bekijkt elk dossier en neemt de medische beslissingen. Voor jou betekent het snellere afspraken tegen een lager tarief."}}},{"type":"gidsTijdlijn","label":"In een verzuimtraject","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Wet verbetering poortwachter","heading":"De bedrijfsarts in een verzuimtraject","text":"Op deze momenten komt de bedrijfsarts in beeld. De weken tellen vanaf de eerste ziektedag.","items":[{"wanneer":"Week 1","titel":"Ziekmelding en triage","wie":"Casemanager","tekst":"Je meldt je medewerker ziek bij de arbodienst. De casemanager belt en schat in of een snel spreekuur nodig is. Bij een duidelijk kortdurende ziekte hoeft de bedrijfsarts nog niets te doen."},{"wanneer":"Week 2 tot 5","titel":"Eerste spreekuur","wie":"Bedrijfsarts","tekst":"Duurt het langer, dan ziet de bedrijfsarts je medewerker op het spreekuur, in Eindhoven of online. Het gesprek gaat over klachten, behandeling, werk en wat er nodig is om terug te kunnen."},{"wanneer":"Week 6","titel":"Probleemanalyse","wie":"Bedrijfsarts","tekst":"De bedrijfsarts legt vast wat je medewerker kan en niet kan, wat de verwachting is en welk advies geldt voor de re-integratie. Jij krijgt de probleemanalyse zonder medische details."},{"wanneer":"Week 8","titel":"Advies bij het plan van aanpak","wie":"Werkgever en werknemer","tekst":"Jullie maken het plan van aanpak op basis van de probleemanalyse. De casemanager helpt; bij vragen over belastbaarheid kijkt de bedrijfsarts mee."},{"wanneer":"Elke 6 weken","titel":"Vervolgspreekuren","wie":"Bedrijfsarts of ondersteuner","tekst":"Zolang het verzuim duurt, volgt de bedrijfsarts de belastbaarheid en past het advies aan. Elk spreekuur levert een korte terugkoppeling aan jou op."},{"wanneer":"Week 42 tot 52","titel":"Belastbaarheidsprofiel","wie":"Bedrijfsarts","tekst":"Is terugkeer in het eigen werk onzeker, dan stelt de bedrijfsarts een belastbaarheidsprofiel op. Daarmee onderzoekt de arbeidsdeskundige welk werk nog passend is."},{"wanneer":"Week 91","titel":"Actueel oordeel","wie":"Bedrijfsarts","tekst":"Voor de WIA-aanvraag beschrijft de bedrijfsarts de huidige belastbaarheid en het verloop van het traject. Dit oordeel gaat met het re-integratieverslag mee naar UWV."}],"noot":"Een spreekuur bij de bedrijfsarts is geen controle. Je medewerker is verplicht te komen, maar het doel is een advies waar jullie allebei mee verder kunnen."}},{"type":"gidsTekst","label":"Wat je te horen krijgt","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Wat je wel en niet te horen krijgt","tekst":"De bedrijfsarts heeft een medisch beroepsgeheim, ook tegenover jou als opdrachtgever. Diagnose, klachten en behandeling blijven tussen de arts en je medewerker. Dat is geen hindernis maar een voorwaarde: alleen zo durft een medewerker open te zijn, en alleen zo blijft het advies betrouwbaar.\n\nWat je **wél** krijgt, is alles wat je nodig hebt om de re-integratie te sturen:\n\n- de functionele beperkingen en mogelijkheden: wat kan je medewerker aan, in uren en in taken\n- de verwachte duur van het verzuim en de prognose\n- het advies voor werkhervatting, een opbouwschema en eventuele aanpassingen\n- of je medewerker meewerkt aan het herstel\n- of er sprake is van een arbeidsconflict, en het advies daarbij\n\nWat je **niet** krijgt: de diagnose, de behandeling, de medicatie en alles wat je medewerker in vertrouwen vertelt. Vraag er ook niet naar, ook niet aan je medewerker zelf: de Autoriteit Persoonsgegevens verbiedt werkgevers om medische gegevens vast te leggen, ook als een medewerker ze uit zichzelf deelt.\n\nIs je medewerker het niet eens met het oordeel van de bedrijfsarts? Dan heeft hij of zij recht op een **second opinion** bij een andere bedrijfsarts, uit een andere arbodienst, op jouw kosten. Dat is sinds 2017 verplicht geregeld in elk basiscontract. En ben jij het niet eens met het advies, of je medewerker niet met het jouwe? Dan is er het deskundigenoordeel van UWV.","kader":{"eyebrow":"Privacy","titel":"Wat jij mag vastleggen","tekst":"De datum van de ziekmelding, de verwachte duur, het percentage dat je medewerker kan werken, de afspraken over passend werk en of het verzuim met een vangnet samenhangt. Geen klachten, geen diagnose, geen gespreksverslagen over de gezondheid.","href":"/je-rechten-en-privacy","label":"Wat je medewerker mag verwachten"}}},{"type":"gidsTekst","label":"Bedrijfsarts, arboarts, huisarts","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Bedrijfsarts, arboarts, huisarts en verzekeringsarts","tekst":"De namen lijken op elkaar, de rollen niet.\n\n- **Bedrijfsarts**: geregistreerd specialist arbeid en gezondheid. Beoordeelt belastbaarheid, adviseert werkgever en werknemer, tekent de probleemanalyse en het actueel oordeel.\n- **Arboarts**: een basisarts die bij een arbodienst werkt onder supervisie van een bedrijfsarts. Mag spreekuren doen, maar niet zelfstandig de wettelijke taken van de bedrijfsarts uitvoeren.\n- **Huisarts**: behandelt. Geeft geen oordeel over werk en schrijft geen verklaringen voor de werkgever; de beroepsorganisatie van huisartsen raadt dat uitdrukkelijk af.\n- **Verzekeringsarts**: werkt bij UWV en beoordeelt bij de WIA-aanvraag de arbeidsongeschiktheid. Werkt onafhankelijk van de bedrijfsarts, maar leest wel diens oordeel.\n- **Arbeidsdeskundige**: geen arts. Vertaalt het belastbaarheidsprofiel van de bedrijfsarts naar werk: welke functie past er nog? Lees de [gids over het arbeidsdeskundig onderzoek](/arbeidsdeskundig-onderzoek).\n\nBij een ziekmelding ga je dus niet naar de huisarts voor een verklaring, maar naar de bedrijfsarts voor een advies. En het laatste woord over een uitkering heeft de verzekeringsarts, niet de bedrijfsarts."}},{"type":"gidsTabel","label":"Basiscontract","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Arbowet","heading":"Wat het basiscontract minimaal regelt","text":"Sinds 1 juli 2017 moet elke werkgever een basiscontract hebben met een arbodienst of een zelfstandige bedrijfsarts. Deze onderdelen horen er wettelijk in te staan.","kolommen":["Onderdeel","Wat het inhoudt","Voor wie"],"rijen":[["Toegang tot de bedrijfsarts","Elke medewerker kan de bedrijfsarts bezoeken, ook zonder ziekmelding: het open spreekuur","Werknemer"],["Verzuimbegeleiding","De bedrijfsarts begeleidt bij ziekte en adviseert over re-integratie, volgens de Wet verbetering poortwachter","Werkgever en werknemer"],["Second opinion","Een medewerker die het oneens is met de bedrijfsarts mag een tweede bedrijfsarts raadplegen, op kosten van de werkgever","Werknemer"],["Werkplekbezoek","De bedrijfsarts mag elke werkplek bezoeken om de arbeidsomstandigheden te beoordelen","Bedrijfsarts"],["Overleg","De bedrijfsarts overlegt met de preventiemedewerker en de ondernemingsraad of personeelsvertegenwoordiging","Preventiemedewerker en OR"],["Klachtenprocedure","Een procedure voor klachten over de bedrijfsarts of de arbodienst","Werkgever en werknemer"],["Beroepsziekten","De bedrijfsarts signaleert beroepsziekten en meldt ze bij het Nederlands Centrum voor Beroepsziekten","Bedrijfsarts"],["Advies over preventie","De bedrijfsarts adviseert over gezond en veilig werken, naast de verzuimbegeleiding","Werkgever"]],"noot":"Ontbreekt een basiscontract of is het onvolledig, dan kan de Nederlandse Arbeidsinspectie een boete opleggen. Bij React2u zit dit alles standaard in het contract."}},{"type":"gidsTekst","label":"Kosten","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Wat kost een bedrijfsarts?","tekst":"De meeste arbodiensten rekenen de bedrijfsarts per uur, naast een abonnement voor het casemanagement. Bij React2u is dat niet anders, en de tarieven staan open op de [prijslijst](/verzuimabonnementen):\n\n- **Bedrijfsarts**: 240 euro per uur.\n- **Ondersteuner van de bedrijfsarts (praktijkondersteuner, onder taakdelegatie)**: 186,50 euro per uur.\n- **Preventief spreekuur en keuringen**: het uurtarief van de bedrijfsarts.\n- **Casemanagement**: in het verzuimabonnement, per werknemer per jaar; de bedrijfsarts zit daar niet in.\n\nEen spreekuur duurt doorgaans een half uur tot drie kwartier, een probleemanalyse ongeveer een uur inclusief rapportage. Een gemiddeld verzuimtraject van een paar maanden komt zo op enkele uren bedrijfsarts. Veel werkgevers vinden dat meevallen, zeker tegenover de kosten van het verzuim zelf: lees [Wat kost een zieke werknemer écht?](/blog/kosten-zieke-werknemer)\n\nWil je weten wat het voor jouw organisatie betekent? Vraag een [offerte](/kennismaken) aan; je krijgt binnen twee werkdagen antwoord.","kader":{"eyebrow":"Tarieven","titel":"Vaste prijzen, geen verrassingen","tekst":"Alle tarieven staan op de prijslijst en gelden voor het hele jaar. Je weet dus vooraf wat een spreekuur, een probleemanalyse of een arbeidsdeskundig onderzoek kost.","href":"/verzuimabonnementen","label":"Bekijk de prijslijst"}}},{"type":"gidsVragen","label":"Veelgestelde vragen","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Veelgestelde vragen","heading":"Vragen over de bedrijfsarts","text":"Staat je vraag er niet bij? Bel ons gerust, ook als je nog geen klant bent.","items":[{"question":"Ben ik als kleine werkgever verplicht een bedrijfsarts te hebben?","answer":"Ja. De Arbowet verplicht elke werkgever met personeel, ook met één medewerker, om een basiscontract te hebben met een arbodienst of een zelfstandige bedrijfsarts. Zonder dat contract kan de Nederlandse Arbeidsinspectie een boete opleggen."},{"question":"Mag mijn medewerker weigeren naar de bedrijfsarts te gaan?","answer":"Nee. Meewerken aan de verzuimbegeleiding hoort bij de verplichtingen van je medewerker. Komt hij of zij zonder goede reden niet, dan mag je na een schriftelijke waarschuwing het loon opschorten."},{"question":"Mag de bedrijfsarts zeggen of mijn medewerker echt ziek is?","answer":"De bedrijfsarts beoordeelt of er beperkingen zijn door ziekte en wat je medewerker nog kan. Het oordeel gaat over arbeidsongeschiktheid voor het eigen werk, niet over de diagnose. Twijfel je aan het oordeel, dan kun je een deskundigenoordeel aanvragen bij UWV."},{"question":"Hoe snel kan mijn medewerker bij de bedrijfsarts terecht?","answer":"Bij React2u binnen een paar dagen, en bij een dringende vraag sneller. Het eerste contact na een ziekmelding is met je casemanager, binnen één werkdag; die plant het spreekuur als dat nodig is."},{"question":"Mag ik zelf naar de bedrijfsarts bellen met vragen over een medewerker?","answer":"Ja, over de belastbaarheid, het advies en de voortgang. Niet over de diagnose: die krijg je niet. In de praktijk loopt het contact via je casemanager, die de bedrijfsarts erbij haalt als het medisch wordt."},{"question":"Wat is het open spreekuur?","answer":"Een spreekuur waar elke medewerker zonder ziekmelding en zonder jouw medeweten terechtkan met vragen over gezondheid en werk. Het is verplicht onderdeel van het basiscontract en bedoeld om uitval te voorkomen."},{"question":"Kan ik van bedrijfsarts of arbodienst wisselen tijdens een lopend dossier?","answer":"Ja. Lopende dossiers nemen we over, zodat er geen termijn wordt gemist. Je medewerker krijgt een nieuwe bedrijfsarts die het dossier leest en, als dat nodig is, een nieuw spreekuur plant."}]}},{"type":"gidsHelpt","label":"Zo helpt React2u","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Zo helpt React2u","heading":"Een bedrijfsarts die je mensen kent, en een casemanager die alles regelt","tekst":"Bij React2u werken de bedrijfsarts, de praktijkondersteuner en je vaste casemanager als één team. Je medewerker wordt snel gezien, jij krijgt een advies waar je iets mee kunt, en het dossier blijft op orde voor UWV. Het basiscontract regelt alles wat de wet vraagt, zonder kleine lettertjes.","punten":["Spreekuur binnen een paar dagen, in Eindhoven of online","Open spreekuur en second opinion standaard in het contract","Taakdelegatie: vaker contact tegen een lager tarief","SBCA gecertificeerd en ISO 9001, 27001 en 27701"],"dienst":{"naam":"Recover","wat":"Verzuimbegeleiding voor werkgevers","tekst":"Casemanagement, bedrijfsarts en taakdelegatie, poortwachterdossier en UWV.","href":"/recover","label":"Meer over React2u Recover"},"kennismaken":{"label":"Kennismaken","href":"/kennismaken"},"belTekst":"Of bel 085 620 58 00, ma t/m vr 9.00 tot 17.00 uur.","verwant":[{"label":"Gids: Wet verbetering poortwachter","href":"/wet-verbetering-poortwachter"},{"label":"Gids: arbeidsdeskundig onderzoek","href":"/arbeidsdeskundig-onderzoek"},{"label":"Gids: preventiemedewerker","href":"/preventiemedewerker"},{"label":"Prijslijst en verzuimabonnementen","href":"/verzuimabonnementen"}]}},{"type":"homeContact","label":"Contact","data":{"eyebrow":"Contact","heading":"Een vraag?\nBel gewoon even.","text":"Bel van maandag tot en met vrijdag tussen 9.00 en 17.00 uur, dan neemt een van ons op.","image":"/beeld/home/even-bellen.webp","alt":"Een vrouw belt ontspannen met React2u","focus":"52% 22%","routes":[{"icon":"phone","label":"Bellen · ma t/m vr 9.00 tot 17.00 uur","value":"085 620 58 00","href":"tel:+31856205800"},{"icon":"mail","label":"Mailen","value":"info@react2u.nl","href":"mailto:info@react2u.nl"},{"icon":"clock","label":"Liever teruggebeld?","value":"Plan een terugbelmoment","href":"/contact"}],"bg":"#ffffff"}}]$concept$::jsonb) with ordinality as t(b, i)
where p.slug = 'bedrijfsarts';

update public.pages
set updated_at = now(),
    published = true
where slug = 'bedrijfsarts';

